9415","description":"Telescope","correct_answer":true},{"id":"01a218eb-5548-7bb0-b947-b85bb9cc7e5d","description":"Periscope","correct_answer":false},{"id":"01a218eb-5548-7f31-955d-74faae379ce5","description":"Endoscope","correct_answer":false},{"id":"01a218eb-5548-72bb-8c73-c2122424f49e","description":"Microscope","correct_answer":false}]},{"id":"01a218eb-5548-7869-8ab5-b31da14014f3","locale":"en-US","category":"01a21312-b489-7df1-b0c8-10e72868dcc8","question":"What theory describes the start of our universe?","difficulty":1,"explanation":"The Big Bang theory describes the universe expanding from an extremely hot, dense state. The cosmic microwave background is often described as the afterglow of that early universe.","alternatives":[{"id":"01a218eb-5548-7e0d-92eb-e0e9533ad91d","description":"Big Bang","correct_answer":true},{"id":"01a218eb-5548-7f72-8ca1-9afadfd4a8f4","description":"Supernova","correct_answer":false},{"id":"01a218eb-5548-70ef-9ed4-44ac8028ef1a","description":"Standard model","correct_answer":false},{"id":"01a218eb-5548-7936-a631-0159ceae7685","description":"Special relativity","correct_answer":false}]},{"id":"01a218eb-5548-74f6-8c7b-379741ede531","locale":"en-US","category":"01a21312-b489-7df1-b0c8-10e72868dcc8","question":"What is the direct cause of Type I Diabetes?","difficulty":1,"explanation":"In Type I diabetes, the immune system destroys insulin-producing beta cells in the pancreas, so blood glucose can build up.","alternatives":[{"id":"01a218eb-5548-7732-b61d-b7d0457e64f2","description":"Not enough insulin","correct_answer":true},{"id":"01a218eb-5548-75d9-b940-285da316a86c","description":"Not enough estrogen","correct_answer":false},{"id":"01a218eb-5548-7fdd-9022-ce8342c5a0ae","description":"Not enough calcium","correct_answer":false},{"id":"01a218eb-5548-7eae-886a-036e08f3ea93","description":"Not enough magnesium","correct_answer":false}]},{"id":"01a218eb-5548-7474-bd49-cca65f428114","locale":"en-US","category":"01a21312-b489-7df1-b0c8-10